import 'dart:convert';
import 'dart:io';
import 'dart:isolate';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:momento_booth/models/open_source_package.dart';

/// Generated by `just gen-licenses`, see tool/generate_licenses.dart.
const String openSourceLicensesAsset = 'assets/licenses/licenses.json.gz';

/// Provides the license information of all third-party software MomentoBooth uses.
class OpenSourceLicensesRepository {

  Future<List<OpenSourcePackage>>? _packages;

  /// Returns all packages from [openSourceLicensesAsset], or an empty list when the asset has not been generated.
  /// The result is loaded once and kept for the rest of the session (about 4 MB, mostly license texts).
  Future<List<OpenSourcePackage>> getAll() => _packages ??= _load();

  Future<List<OpenSourcePackage>> _load() async {
    final ByteData data;
    try {
      data = await rootBundle.load(openSourceLicensesAsset);
    } on FlutterError {
      return const [];
    }
    final bytes = data.buffer.asUint8List(data.offsetInBytes, data.lengthInBytes);
    return Isolate.run(() => decode(bytes));
  }

  /// Decodes the gzipped JSON written by tool/generate_licenses.dart.
  @visibleForTesting
  static List<OpenSourcePackage> decode(Uint8List bytes) {
    final json = jsonDecode(utf8.decode(gzip.decode(bytes))) as Map<String, dynamic>;
    // License texts are stored once and referenced by index, as many packages share the same text.
    final texts = (json['texts'] as List).cast<String>();
    return [
      for (final package in (json['packages'] as List).cast<Map<String, dynamic>>())
        OpenSourcePackage.fromJson({
          ...package,
          'licenseText': switch (package['licenseText']) {
            final int index => texts[index],
            _ => null,
          },
        }),
    ];
  }

}
